DO $$
DECLARE
  rec RECORD;
BEGIN
  FOR rec IN
    SELECT claim_id, denial_code, billed_amount, status
    FROM claims
    ORDER BY submission_date, claim_id
  LOOP
    IF rec.denial_code = 'CO-45' AND rec.billed_amount > 500 THEN
      UPDATE claims
      SET billed_amount = billed_amount * 0.85
      WHERE claim_id = rec.claim_id;

      SELECT billed_amount, status INTO rec.billed_amount, rec.status
      FROM claims
      WHERE claim_id = rec.claim_id;
    END IF;

    IF rec.billed_amount <= 200 THEN
      UPDATE claims
      SET status = 'WITHDRAWN'
      WHERE claim_id = rec.claim_id;

      SELECT status INTO rec.status
      FROM claims
      WHERE claim_id = rec.claim_id;
    END IF;

    IF rec.status = 'PENDING' AND rec.denial_code = 'PR-1' THEN
      UPDATE claims
      SET billed_amount = billed_amount + 50
      WHERE claim_id = rec.claim_id;
    END IF;
  END LOOP;
END $$;

SELECT * FROM claims ORDER BY claim_id;
